```js
// verifier.js
const crypto = require('crypto');
const fetch = require('node-fetch');

// 1️⃣ Verify PulseDAO signature
function verifyPulse({json, signature, pubKey}){
  const msgHash = crypto.createHash('sha256').update(JSON.stringify(json)).digest();
  return crypto.verify(null, msgHash, {key:pubKey, format:'pem', type:'spki'}, Buffer.from(signature,'hex'));
}

// 2️⃣ Pull CO2 intensity
async function getCO2(){
  const r = await fetch('https://api.carbonintensity.org.uk/intensity');
  const {data:{intensity:{value}}} = await r.json();
  return value; // gCO2eq per kWh
}

// 3️⃣ Calculate TE-R
async function calcTE(json, sig, pub){
  if(!verifyPulse({json,sig,pub})) throw new Error('Invalid signature');
  const trust = json.trustScore; // assume trust score in 0‑1 range
  const co2 = await getCO2();
  return trust / co2;
}

// Example usage
const pulse = {id:123, trustScore:0.85, content:'Hello'};
const sig = '...' // hex signature from PulseDAO
const pubKey = '-----BEGIN PUBLIC KEY-----\n...\n-----END PUBLIC KEY-----';
calcTE(pulse,sig,pubKey).then(r=>{console.log('TE‑R:',r);});
```

